import React, { useState } from 'react';
import MeshSphere from '../components/MeshSphere';
import { analyzeThought } from '../hooks/useGroq';
import { useThoughts } from '../hooks/useStorage';

const TRAPS = ['Katastrofiering','Tankeläsning','Svartvitt tänkande','Övergeneralisering','Känslomässigt resonerande','Personalisering','Filtrerande','Bör-tänkande'];

export default function Home({ setPage, streak }) {
  const [text,    setText]    = useState('');
  const [loading, setLoading] = useState(false);
  const [error,   setError]   = useState('');
  const [result,  setResult]  = useState(null);
  const { addThought } = useThoughts();

  const handleSubmit = async () => {
    if (!text.trim() || loading) return;
    setLoading(true); setError('');
    try {
      const ai = await analyzeThought(text);
      const entry = { id:Date.now(), user_text:text, ...ai, date:new Date().toISOString() };
      addThought(entry); setResult(entry);
    } catch { setError('Kunde inte analysera. Försök igen.'); }
    setLoading(false);
  };

  if (result) return <Analysis result={result} text={text} onBack={()=>{setResult(null);setText('');}} setPage={setPage} />;

  return (
    <div style={{ minHeight:'100vh', background:'#0c0c0e', paddingTop:56, paddingBottom:96, position:'relative', overflow:'hidden' }}>
      <div style={{ position:'absolute', inset:0, backgroundImage:'radial-gradient(circle at 30% 20%, rgba(80,60,120,0.15) 0%, transparent 50%), radial-gradient(circle at 80% 70%, rgba(40,40,80,0.12) 0%, transparent 50%)', pointerEvents:'none' }} />

      {/* Sphere */}
      <div style={{ display:'flex', justifyContent:'center', marginTop:4, position:'relative', animation:'fadeIn .9s ease both' }}>
        <div style={{ position:'relative' }}>
          <MeshSphere size={340} speed={0.5} distort={0.7} color='#f2f0eb' />
          {streak > 0 && (
            <div style={{ position:'absolute', top:36, right:-8, background:'rgba(242,240,235,0.95)', color:'#0c0c0e', padding:'5px 12px', borderRadius:100, fontSize:11, fontWeight:700, fontFamily:'DM Mono,monospace', letterSpacing:'0.06em', boxShadow:'0 4px 16px rgba(0,0,0,0.4)' }}>
              🔥 {streak}
            </div>
          )}
          <div style={{ position:'absolute', bottom:30, left:'50%', transform:'translateX(-50%)', whiteSpace:'nowrap' }}>
            <span style={{ fontFamily:'DM Mono,monospace', fontSize:9, letterSpacing:'0.22em', textTransform:'uppercase', color:'rgba(242,240,235,0.28)' }}>Tankemönster · KBT</span>
          </div>
        </div>
      </div>

      {/* Heading */}
      <div style={{ padding:'0 24px', textAlign:'center', marginBottom:24, animation:'fadeUp .8s .1s both' }}>
        <h1 style={{ fontSize:'clamp(40px,10vw,64px)', fontWeight:900, letterSpacing:'-0.06em', lineHeight:0.86, color:'#f2f0eb', textTransform:'uppercase' }}>
          BRYT<br/><span style={{ color:'rgba(242,240,235,0.18)' }}>SPIRALEN</span>
        </h1>
      </div>

      {/* Ticker */}
      <div style={{ overflow:'hidden', marginBottom:24, borderTop:'1px solid rgba(255,255,255,0.05)', borderBottom:'1px solid rgba(255,255,255,0.05)', padding:'7px 0' }}>
        <div style={{ display:'flex', animation:'ticker 26s linear infinite', width:'200%' }}>
          {[...TRAPS,...TRAPS].map((t,i)=>(
            <span key={i} style={{ fontFamily:'DM Mono,monospace', fontSize:9, letterSpacing:'0.16em', textTransform:'uppercase', color:'rgba(242,240,235,0.2)', whiteSpace:'nowrap', padding:'0 24px' }}>{t} ·</span>
          ))}
        </div>
      </div>

      {/* Input — liquid glass card */}
      <div style={{ padding:'0 16px', animation:'fadeUp .8s .2s both' }}>
        <div className="liq-solid" style={{ marginBottom:10, overflow:'hidden' }}>
          <div style={{ padding:'16px 18px 10px' }}>
            <div style={{ fontFamily:'DM Mono,monospace', fontSize:9, letterSpacing:'0.2em', textTransform:'uppercase', color:'rgba(242,240,235,0.3)', marginBottom:12, display:'flex', alignItems:'center', gap:8 }}>
              <span style={{ width:5, height:5, borderRadius:'50%', background:'rgba(242,240,235,0.5)', display:'inline-block', animation:'pulse 2.5s infinite' }} />
              Tanke · Input
            </div>
            <textarea value={text} onChange={e=>setText(e.target.value)} maxLength={1000}
              placeholder="Vad snurrar i huvudet just nu?"
              style={{ width:'100%', minHeight:100, background:'transparent', border:'none', color:'#f2f0eb', fontSize:15, fontWeight:300, lineHeight:1.8, resize:'none', outline:'none' }}
            />
          </div>
          <div style={{ borderTop:'1px solid rgba(255,255,255,0.07)', padding:'10px 18px', display:'flex', justifyContent:'space-between', alignItems:'center' }}>
            <span style={{ fontFamily:'DM Mono,monospace', fontSize:9, color:'rgba(242,240,235,0.18)' }}>{text.length}/1000</span>
            <button onClick={handleSubmit} disabled={!text.trim()||loading}
              style={{ padding:'9px 20px', borderRadius:12, background: text.trim()&&!loading ? 'rgba(242,240,235,0.95)' : 'rgba(255,255,255,0.08)', color: text.trim()&&!loading ? '#0c0c0e' : 'rgba(242,240,235,0.25)', fontSize:11, fontWeight:700, letterSpacing:'0.1em', textTransform:'uppercase', fontFamily:'DM Mono,monospace', transition:'all .25s', border: text.trim()&&!loading ? 'none' : '1px solid rgba(255,255,255,0.08)', boxShadow: text.trim()&&!loading ? '0 4px 16px rgba(0,0,0,0.3)' : 'none' }}>
              {loading ? <span style={{ display:'flex',alignItems:'center',gap:8 }}><span style={{ width:10,height:10,border:'2px solid rgba(0,0,0,0.2)',borderTopColor:'#0c0c0e',borderRadius:'50%',display:'inline-block',animation:'spin .7s linear infinite' }}/>Analyserar</span> : 'Analysera →'}
            </button>
          </div>
          {error && <p style={{ padding:'0 18px 12px', color:'rgba(255,120,120,0.85)', fontSize:12 }}>{error}</p>}
        </div>

        {/* Quick actions — two liquid glass pills */}
        <div style={{ display:'flex', gap:8 }}>
          {[
            { id:'checkin',   icon:'◈', label:'Check-in',  sub:'Hur mår du?' },
            { id:'breathing', icon:'◯', label:'Andning',   sub:'4-7-8' },
          ].map(({ id, icon, label, sub }) => (
            <button key={id} onClick={()=>setPage(id)} className="liq"
              style={{ flex:1, padding:'13px 14px', display:'flex', alignItems:'center', gap:10, transition:'all .25s', textAlign:'left' }}
              onMouseEnter={e=>e.currentTarget.style.background='linear-gradient(135deg, rgba(255,255,255,0.14) 0%, rgba(255,255,255,0.07) 100%)'}
              onMouseLeave={e=>e.currentTarget.style.background='linear-gradient(135deg, rgba(255,255,255,0.09) 0%, rgba(255,255,255,0.04) 100%)'}>
              <span style={{ fontSize:18, color:'rgba(242,240,235,0.6)' }}>{icon}</span>
              <div>
                <div style={{ fontSize:12, fontWeight:600, color:'rgba(242,240,235,0.8)', letterSpacing:'-0.01em' }}>{label}</div>
                <div style={{ fontFamily:'DM Mono,monospace', fontSize:8, color:'rgba(242,240,235,0.3)', letterSpacing:'0.1em', textTransform:'uppercase', marginTop:1 }}>{sub}</div>
              </div>
            </button>
          ))}
        </div>
      </div>
    </div>
  );
}

function Analysis({ result, text, onBack, setPage }) {
  return (
    <div style={{ minHeight:'100vh', background:'#0c0c0e', paddingTop:56, paddingBottom:96, position:'relative', overflow:'hidden' }}>
      <div style={{ position:'absolute', inset:0, backgroundImage:'radial-gradient(circle at 70% 10%, rgba(100,40,80,0.14) 0%, transparent 50%)', pointerEvents:'none' }} />

      <div style={{ padding:'20px 16px 0', animation:'fadeUp .6s cubic-bezier(0.16,1,0.3,1) both' }}>
        <div style={{ display:'flex', justifyContent:'center', marginBottom:20 }}>
          <MeshSphere size={200} speed={0.3} distort={1.2} color='#f2f0eb' />
        </div>

        {/* Quote */}
        <div className="liq" style={{ padding:'14px 18px', marginBottom:16, borderRadius:16 }}>
          <div style={{ fontFamily:'DM Mono,monospace', fontSize:8, letterSpacing:'0.2em', textTransform:'uppercase', color:'rgba(242,240,235,0.25)', marginBottom:7 }}>Du skrev</div>
          <p style={{ fontSize:13, color:'rgba(242,240,235,0.5)', fontStyle:'italic', lineHeight:1.75 }}>"{text.slice(0,140)}{text.length>140?'...':''}"</p>
        </div>

        {/* Trap */}
        <div style={{ marginBottom:18, padding:'0 2px' }}>
          <div style={{ fontFamily:'DM Mono,monospace', fontSize:9, letterSpacing:'0.2em', textTransform:'uppercase', color:'rgba(242,240,235,0.28)', marginBottom:6 }}>{result.trap_icon} Tankefälla</div>
          <h2 style={{ fontSize:'clamp(28px,7vw,46px)', fontWeight:900, letterSpacing:'-0.05em', lineHeight:0.9, color:'#f2f0eb', textTransform:'uppercase' }}>{result.trap_label}</h2>
        </div>

        {/* Info cards */}
        {[
          { label:'Analys',    body:result.description },
          { label:'Omramning', body:result.reframe },
          { label:'Övning',    body:result.exercise_text },
        ].map(({ label, body }) => (
          <div key={label} className="liq" style={{ marginBottom:10, padding:'16px 18px', borderRadius:16 }}>
            <div style={{ fontFamily:'DM Mono,monospace', fontSize:8, letterSpacing:'0.18em', textTransform:'uppercase', color:'rgba(242,240,235,0.28)', marginBottom:9 }}>{label}</div>
            <p style={{ fontSize:13, color:'rgba(242,240,235,0.78)', lineHeight:1.88, fontWeight:300 }}>{body}</p>
          </div>
        ))}

        <div style={{ display:'flex', gap:8, marginTop:8 }}>
          <button onClick={()=>setPage('breathing')} className="liq"
            style={{ flex:1, padding:'13px', borderRadius:14, color:'rgba(242,240,235,0.6)', fontSize:11, fontFamily:'DM Mono,monospace', letterSpacing:'0.1em', textTransform:'uppercase', transition:'all .2s' }}>
            ◯ Andning
          </button>
          <button onClick={onBack} style={{ padding:'13px 20px', fontSize:11, color:'rgba(242,240,235,0.28)', fontFamily:'DM Mono,monospace', letterSpacing:'0.1em', textTransform:'uppercase' }}>
            ← Tillbaka
          </button>
        </div>
      </div>
    </div>
  );
}
